/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  width: calc(100% - 2 * var(--gap));
  max-width: 44rem;
  margin: clamp(1rem, 5vw, 3rem) auto;
  padding: clamp(1.25rem, 4vw, 2.25rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1,
.sheet h2 {
  margin: 0;
  line-height: 1.15;
}

.sheet h1 {
  font-size: clamp(1.625rem, 4vw, 2rem);
}

.sheet > h1 + p,
.sheet dialog p {
  margin: 0.5rem 0 0;
  color: var(--subtle);
}

.sheet form {
  margin-top: 1.5rem;
}

.sheet label {
  display: block;
  margin: var(--gap) 0 0.375rem;
  font-weight: 600;
}

.sheet input,
.sheet select,
.sheet button {
  min-height: 44px;
  padding: 0.625rem 0.875rem;
  border: 1px solid var(--subtle);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet input,
.sheet select {
  display: block;
  width: 100%;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.sheet button {
  max-width: 100%;
  font-weight: 600;
  overflow-wrap: anywhere;
  white-space: normal;
}

.sheet [data-primary],
.sheet #confirm {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.sheet button:focus-visible,
.sheet input:focus-visible,
.sheet select:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.sheet input[aria-invalid=\"true\"] {
  border-color: var(--danger);
  box-shadow: inset 0 0 0 1px var(--danger);
}

.sheet [role=\"alert\"] {
  margin: var(--gap) 0 0;
  padding: 0.625rem 0.75rem;
  border-inline-start: 4px solid var(--danger);
  background: var(--canvas);
  color: var(--danger);
  font-weight: 600;
}

.sheet [role=\"status\"] {
  margin: 1.5rem 0 0;
  padding-top: var(--gap);
  border-top: 1px solid var(--line);
  color: var(--subtle);
  overflow-wrap: anywhere;
}

.sheet dialog {
  width: calc(100% - 2 * var(--gap));
  max-width: 28rem;
  padding: clamp(1.25rem, 4vw, 1.75rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet dialog h2 {
  font-size: 1.375rem;
}

.sheet dialog p {
  margin-bottom: 1.25rem;
}

.sheet dialog button + button {
  margin-inline-start: 0.5rem;
}

@media (max-width: 35rem) {
  .actions {
    flex-direction: column;
  }
}
EOF"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const report = id => JSON.parse(readFileSync('visits/' + id + '.json', 'utf8'));
const mobile = report('6aca8dd2-fe05-47d9-a659-6a27077208e5');
const wide = report('b114f953-30c0-4086-9b83-c948efc1372f');
const dialog = report('980a78df-176e-433c-b838-4f30c032cdd6');
const primary = 'Review proposed notification preferences';
const secondary = 'Restore saved values';
const alert = 'Enter a complete email address before reviewing these settings.';
for (const visit of [mobile, wide, dialog]) {
  assert.equal(visit.error, null);
  for (const {state} of visit.timeline.slice(1)) {
    const {geometry} = state;
    assert.equal(geometry.page, geometry.viewport);
    for (const label of [primary, secondary]) {
      const button = geometry.elements.find(element => element.tag === 'BUTTON' && element.text === label);
      assert.ok(button && button.scroll <= button.client && button.h >= 44);
    }
  }
}
const tm = mobile.timeline.map(x => x.state);
const tw = wide.timeline.map(x => x.state);
assert.deepEqual(tm.slice(2,6).map(s => s.focus.id || s.focus.text), ['email', 'rate', primary, secondary]);
assert.equal(tm[4].geometry.elements.find(e => e.text === primary && e.tag === 'BUTTON').outline, 'solid 2px');
assert.equal(tm[5].geometry.elements.find(e => e.text === secondary && e.tag === 'BUTTON').outline, 'solid 2px');
assert.equal(tm[6].focus.text, primary);
assert.equal(tm.at(-1).focus.id, 'email');
assert.equal(tm.at(-1).fields[0].invalid, 'true');
assert.deepEqual(tm.at(-1).status, [alert, 'ops@example.test / Daily']);
assert.equal(tw[3].focus.id, 'cancel');
assert.equal(tw[4].focus.id, 'confirm');
assert.equal(tw[5].dialog.length, 0);
assert.equal(tw[5].focus.id, 'email');
assert.equal(tw[6].dialog.length, 1);
assert.equal(tw[7].dialog.length, 0);
assert.equal(tw[7].focus.text, primary);
assert.deepEqual(tw[7].status, ['ops@example.test / Daily']);
assert.deepEqual(tw[9].status, ['duty@example.test / Daily']);
assert.deepEqual(tw.at(-1).status, ['duty@example.test / Daily']);
assert.equal(tw.at(-1).fields[0].value, 'ops@example.test');
assert.equal(tw.at(-1).fields[0].invalid, 'false');
assert.equal(dialog.timeline.at(-1).state.dialog.length, 1);
console.log('Passed layout, keyboard order, focus, address error, preview, Escape, Cancel, Confirm and Restore.');
for (const visit of [mobile, wide, dialog]) {
  const {geometry, focus} = visit.timeline.at(-1).state;
  console.log(JSON.stringify({width:geometry.viewport, page:geometry.page, focus, elements:geometry.elements.filter(e => e.tag === 'BUTTON' || e.role === 'alert' || e.role === 'dialog')}));
}
NODE
sha256sum dist/*"

