import {readFileSync} from 'node:fs';
for (const id of ['6aca8dd2-fe05-47d9-a659-6a27077208e5','b114f953-30c0-4086-9b83-c948efc1372f']) {
  const report=JSON.parse(readFileSync('visits/'+id+'.json'));
  console.table(report.timeline.map(({action,state:s},i)=>({i,action:action.op,key:action.key??action.target,focus:s.focus.id??s.focus.text,email:s.fields[0].value,invalid:s.fields[0].invalid,dialog:s.dialog.length,status:s.status.join(' | ')})));
}
NODE"

